INSERT INTO requests.requests (
    session_id, project_id, method_id, path, model, is_streaming, message_count, is_tool_loop,
    status_id, request_headers, params, request_body, request_body_size,
    last_user_message, human_prompt, turn_type_id, turn_origin_id, created_at, author_kind_id
)
SELECT 782307, 313870, rm.id, '/v1/messages', 'claude-opus-5', true, 1, false, rs.id,
       '{}'::jsonb, '{}'::jsonb, decode('','hex'), 40381,
       '', '', rtt.id, rto.id, NOW(), ak.id
FROM requests.methods rm, requests.statuses rs,
     requests.turn_types rtt, requests.turn_origins rto, requests.author_kinds ak
WHERE rm.code = 'POST' AND rs.code = 'pending'
  AND rtt.code = 'user_prompt' AND rto.code = 'primary' AND ak.code = 'operator'
